import { Injectable } from '@angular/core';
import { environment } from '../../../../environments/environment';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { advanceFiler, searchedBundles, searchedDetail, searchedSummary, searchRespose } from '../../interfaces/advance-search.interface';

@Injectable({
  providedIn: 'root'
})
export class AdvanceSearchService {
  private url: string = environment.elasticSearchService;
  constructor(private http: HttpClient) {

  }

  async searchBundle(searchTerm: string, nCaseid: string, isCaseSensitive: boolean, isStartWith: boolean, isWholeWord: boolean, jIssues?: string[], jImpact?: string[], jRelevance?: string[], jMarkup?: string[], nBundleid?: string): Promise<searchedBundles> {
    try {
      const obj: any = {
        nCaseid, isCaseSensitive, isStartWith, isWholeWord, searchTerm
      }
      if (jImpact?.length) {
        obj.jImpact = jImpact;
      }
      if (jRelevance?.length) {
        obj.jRelevance = jRelevance;
      }
      if (jIssues?.length) {
        obj.jIssues = jIssues;
      }
      if (jMarkup?.length) {
        obj.jMarkup = jMarkup;
      }

      if (!obj?.jMarkup?.length && (jImpact?.length || jRelevance?.length || jIssues?.length)) {
        obj.jMarkup = ['QF', 'F'];
      }

      if (nBundleid) {
        obj.nBundleid = nBundleid;
      }

      const res: searchedBundles = await firstValueFrom(
        this.http.post<searchedBundles>(`${this.url}/search/bundles`, obj)
      );
      return res
    } catch (error) {
      console.error(error);
      return { msg: -1, bundleIds: [], error: error }
    }
  }


  async search(searchTerm: string, nCaseid: string, isCaseSensitive: boolean, isStartWith: boolean, isWholeWord: boolean, page: number, pageSize: number, jIssues?: string[], jImpact?: string[], jRelevance?: string[], jMarkup?: string[], nBundleid?: string,
    nSectionid?: string, cFolderType?: string
  ): Promise<searchRespose> {
    try {
      const obj: any = {
        nCaseid, isCaseSensitive, isStartWith, isWholeWord, page, pageSize, searchTerm
      }
      if (jImpact?.length) {
        obj.jImpact = jImpact;
      }
      if (jRelevance?.length) {
        obj.jRelevance = jRelevance;
      }
      if (jIssues?.length) {
        obj.jIssues = jIssues;
      }
      if (jMarkup?.length) {
        obj.jMarkup = jMarkup;
      }

      if (!obj?.jMarkup?.length && (jImpact?.length || jRelevance?.length || jIssues?.length)) {
        obj.jMarkup = ['QF', 'F'];
      }
      if (nBundleid) {
        obj.nBundleid = nBundleid;
      }

      obj.nSectionid = nSectionid;
      obj.cFolderType = cFolderType;

      const res: searchRespose = await firstValueFrom(
        this.http.post<searchRespose>(`${this.url}/search`, obj)
      );
      return res;
    } catch (error) {
      console.error(error);
      return { msg: -1, data: [], error };
    }
  }


  async searchSummary(searchTerm: string, nCaseid: string, isCaseSensitive: boolean, isStartWith: boolean, isWholeWord: boolean, jIssues?: string[], jImpact?: string[], jRelevance?: string[], jMarkup?: string[], nBundleid?: string,
    nSectionid?: string, cFolderType?: string
  ): Promise<searchedSummary> {
    try {
      const obj: any = {
        nCaseid, isCaseSensitive, isStartWith, isWholeWord, searchTerm
      }
      if (jImpact?.length) {
        obj.jImpact = jImpact;
      }
      if (jRelevance?.length) {
        obj.jRelevance = jRelevance;
      }
      if (jIssues?.length) {
        obj.jIssues = jIssues;
      }
      if (jMarkup?.length) {
        obj.jMarkup = jMarkup;
      }

      if (!obj?.jMarkup?.length && (jImpact?.length || jRelevance?.length || jIssues?.length)) {
        obj.jMarkup = ['QF', 'F'];
      }

      if (nBundleid) {
        obj.nBundleid = nBundleid;
      }

      obj.nSectionid = nSectionid;
      obj.cFolderType = cFolderType;
      const res: searchedSummary = await firstValueFrom(
        this.http.post<searchedSummary>(`${this.url}/search/summary`, obj)
      );
      return res
    } catch (error) {
      console.error(error);
      return { msg: -1, totalBDIDs: 0, error: error }
    }
  }


  async searchDetail(searchTerm: string, nCaseid: string, isCaseSensitive: boolean, isStartWith: boolean, isWholeWord: boolean, nBundledetailid: string): Promise<searchedDetail> {
    try {
      const res: searchedDetail = await firstValueFrom(
        this.http.post<searchedDetail>(`${this.url}/search/detail`, {
          nCaseid, isCaseSensitive, isStartWith, isWholeWord, nBundledetailid, searchTerm
        })
      );
      return res
    } catch (error) {
      console.error(error);
      return { msg: -1, totalMatches: 0, totalPages: 0, pages: [], error: error }
    }
  }
}
